/// <summary>
/// MPJ_19962_MDRPOTransactionalMissingFields kavya 25/3/2022
/// The Entity extension
/// </summary>
[ExtensionOf(dataentityviewstr(PurchPurchaseOrderHeaderV2Entity))]
final class METPurchPurchaseOrderHeaderV2Entity_Extension
{
}

Method.Source:
    /// <summary>
    /// Map data fields to virtual fields
    /// </summary>
    public void postLoad()
    {        
        METPlannerCodeSetup METPlannerCodeSetup; 

        select firstonly PlannerCodePersonnelNumber from METPlannerCodeSetup 
            where METPlannerCodeSetup.PlannerCode == this.METPOPlannerCode;
        
        HcmWorker metHcmWorkerStd = HcmWorker::find(METPlannerCodeSetup.PlannerCodePersonnelNumber);

        this.METPOPlannerContactName    = metHcmWorkerStd.name();
        this.METPOPlannerContactEmail   = metHcmWorkerStd.email();
        this.METPOPlannerContactPhone   = metHcmWorkerStd.phone();

        PurchTable      metpurchTableStd;
        InventLocation  metInventLocationStd;
        METInventLocation METInventLocation;

        select firstonly UseDevAddressforShiptoGLNSetting, PODeliveryShiptoGLN from METInventLocation
            join InventLocationId from metInventLocationStd
            where metInventLocationStd.RecId == METInventLocation.InventLocation
            join DeliveryPostalAddress from metPurchTableStd
            where metPurchTableStd.InventLocationId == metInventLocationStd.InventLocationId
            && metPurchTableStd.PurchId          == this.PurchaseOrderNumber;
                              
        if(METInventLocation.UseDevAddressforShiptoGLNSetting)
        {
            this.METPODeliveryShiptoGLN = metPurchTableStd.deliveryAddress().METPODeliveryShiptoGLN;
        }
        else
        {
            this.METPODeliveryShiptoGLN = METInventLocation.PODeliveryShiptoGLN;
        }

        //MPJ-30932 - Missing fields on PO Table and Confirmation data entities only
                
        this.METWHEmail = PurchTable::find(this.PurchaseOrderNumber).getPOWarehouseAddressContactEmail();
        this.METWHPhone = PurchTable::find(this.PurchaseOrderNumber).getPOWarehouseAddressContactPhone();
        
        //MPJ-30932 - Missing fields on PO Table and Confirmation data entities only
        next postload();
    }

    /// <summary>
    /// CoC method for InsertEntityDataSource method
    /// </summary>
    /// <param name = "_entityCtx">Param of type DataEntityRuntimeContext</param>
    /// <param name = "_dataSourceCtx">Param of type DataEntityDataSourceRuntimeContext</param>
    /// <returns>true of false</returns>
    public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        boolean metRet;
        Common  metBuffer;

        if (_dataSourceCtx.name() == dataEntityDataSourceStr(PurchPurchaseOrderHeaderV2Entity, METPurchTable))
        {
            metBuffer = METPurchTable::find(this.PurchaseOrderNumber, true);
        }

        if (metBuffer)
        {
            _dataSourceCtx.setBuffer(metBuffer);
            _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::Update);
            this.mapEntityToDataSource(_entityCtx, _dataSourceCtx);
        }

        metRet = next insertEntityDataSource(_entityCtx, _dataSourceCtx);
    
        return metRet;
    }

   /// <summary>
   /// Post target process method to approve the purchase orders once all the lines are imported
   /// </summary>
   /// <param name = "_dmfDefinitionGroupExecution">Type DefinitionGroupExecution</param>
   public static void postTargetProcess(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
   {
       DMFDefinitionGroupExecution locDefinitionGroupExecution;

       while select locDefinitionGroupExecution
           where locDefinitionGroupExecution.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup &&
              locDefinitionGroupExecution.ExecutionId == _dmfDefinitionGroupExecution.ExecutionId &&
              locDefinitionGroupExecution.RecId != _dmfDefinitionGroupExecution.RecId &&
              locDefinitionGroupExecution.Entity like METConstants::PurchaseOrderCompositeLike
       {
           if(locDefinitionGroupExecution.EntityXMLName == dataentityviewstr(PurchPurchaseOrderLineV2Entity))
           {
               PurchPurchaseOrderLineV2Entity::postTargetProcess(locDefinitionGroupExecution);
           }
       }
   }
